"use strict";exports.id=9421,exports.ids=[9421],exports.modules={99421:(a,b,c)=>{c.r(b),c.d(b,{articleDetails:()=>d});let d={slug:"social-media-image-dimensions-2025",title:"Social Media Image Dimensions for Every Platform (2025)",metaDesc:"Complete 2025 reference guide for social media image sizes. Instagram, YouTube, Facebook, LinkedIn, TikTok, Twitter/X dimensions and aspect ratios.",publishDate:"2025-07-05",category:"creator",categoryLabel:"Creator Tools",relatedToolSlugs:["social-post-size-checker","image-resizer","image-cropper"],content:'\n<h2>Why Image Dimensions Change Every Year</h2>\n<p>Social media platforms frequently update their display layouts, introducing new content formats (Reels, Shorts, Stories) and changing grid proportions. Using outdated dimension guides results in cropped content, black bars, or compressed graphics that look unprofessional. This guide reflects verified 2025 specifications.</p>\n\n<h2>Instagram Dimensions 2025</h2>\n<ul>\n  <li>Feed post square: 1080 \xd7 1080 px</li>\n  <li>Feed post portrait: 1080 \xd7 1350 px (4:5) — recommended for maximum feed coverage</li>\n  <li>Feed post landscape: 1080 \xd7 566 px (1.91:1)</li>\n  <li>Stories: 1080 \xd7 1920 px (9:16)</li>\n  <li>Reels: 1080 \xd7 1920 px (9:16)</li>\n  <li>Profile picture: 320 \xd7 320 px (displayed as 110 \xd7 110 px circle)</li>\n</ul>\n\n<h2>YouTube Dimensions 2025</h2>\n<ul>\n  <li>Thumbnail: 1280 \xd7 720 px (16:9, max 2 MB)</li>\n  <li>Channel banner: 2560 \xd7 1440 px (safe zone: center 1546 \xd7 423 px)</li>\n  <li>Profile picture: 800 \xd7 800 px (displayed as circle)</li>\n  <li>End screen preview: 1280 \xd7 720 px</li>\n</ul>\n\n<h2>Facebook Dimensions 2025</h2>\n<ul>\n  <li>Feed post: 1200 \xd7 630 px</li>\n  <li>Cover photo: 851 \xd7 315 px desktop / 640 \xd7 360 px mobile</li>\n  <li>Profile picture: 170 \xd7 170 px desktop</li>\n  <li>Stories: 1080 \xd7 1920 px</li>\n</ul>\n\n<h2>LinkedIn Dimensions 2025</h2>\n<ul>\n  <li>Feed image post: 1200 \xd7 627 px (1.91:1)</li>\n  <li>Profile banner: 1584 \xd7 396 px (4:1)</li>\n  <li>Company logo: 300 \xd7 300 px</li>\n  <li>Article header: 1200 \xd7 627 px</li>\n</ul>\n\n<h2>TikTok Dimensions 2025</h2>\n<ul>\n  <li>Video: 1080 \xd7 1920 px (9:16 vertical)</li>\n  <li>Profile picture: 200 \xd7 200 px</li>\n</ul>\n\n<h2>X (Twitter) Dimensions 2025</h2>\n<ul>\n  <li>Tweet image: 1200 \xd7 675 px (16:9)</li>\n  <li>Profile picture: 400 \xd7 400 px</li>\n  <li>Header image: 1500 \xd7 500 px</li>\n</ul>\n\n<h2>Check Your Images Against Platform Specs</h2>\n<p>Upload your image to our <a href="/tools/creator/social-post-size-checker">Social Post Size Checker</a> and select your target platform. The tool overlays the platform\'s crop guides on your image so you can verify that text and key visuals fall within safe zones.</p>\n    '}}};